import { useId, type ReactNode } from 'react'
import type { ProvenanceClass } from '@tuju/contracts'
import { cn } from '#/lib/utils'

/**
 * What kind of non-live, non-authoritative content this is. Defined locally on
 * purpose: it is a presentation concern, not an API contract.
 *
 * - `ai`: generated by a model (solid violet).
 * - `synthetic`: generated market data, not real trading (dashed cyan).
 * - `demo-only`: shown for demonstration only (dashed cyan, like synthetic,
 *   because both mean "not live market data").
 */
export type ProvenanceKind = 'ai' | 'synthetic' | 'demo-only'

const KIND: Record<ProvenanceKind, { label: string; icon: string | null; badge: string; container: string }> = {
  ai: {
    label: 'AI-generated',
    icon: '✦',
    badge: 'border-solid border-ai/40 bg-ai-bg text-ai',
    container: 'border-solid border-ai/40 bg-ai-bg',
  },
  synthetic: {
    label: 'Synthetic data',
    icon: null,
    badge: 'border-dashed border-synthetic/55 bg-synthetic-bg text-synthetic',
    container: 'border-dashed border-synthetic/55 bg-synthetic-bg',
  },
  'demo-only': {
    label: 'Demo only',
    icon: null,
    badge: 'border-dashed border-synthetic/55 bg-synthetic-bg text-synthetic',
    container: 'border-dashed border-synthetic/55 bg-synthetic-bg',
  },
}

export interface ProvenanceBadgeProps {
  kind: ProvenanceKind
  /** Override the default text, e.g. "AI summary". The text is always rendered. */
  label?: string
  className?: string
  id?: string
}

/** Text badge marking content as AI, synthetic or demo-only. Never colour alone. */
export function ProvenanceBadge({ kind, label, className, id }: ProvenanceBadgeProps) {
  const spec = KIND[kind]
  return (
    <span
      id={id}
      data-provenance={kind}
      className={cn(
        'inline-flex h-[18px] items-center gap-1 rounded-sm border px-1.5 text-2xs font-medium tracking-wider whitespace-nowrap uppercase',
        spec.badge,
        className,
      )}
    >
      {spec.icon ? <span aria-hidden="true">{spec.icon}</span> : null}
      {label ?? spec.label}
    </span>
  )
}

export interface ProvenanceContainerProps {
  kind: ProvenanceKind
  /** Badge text override. */
  label?: string
  /** Small print under the content, e.g. "Generated 14 Oct 2026 16:05 MYT · not investment advice". */
  caption?: ReactNode
  children: ReactNode
  className?: string
}

/**
 * Wraps content that is AI-generated, synthetic or demo-only: solid violet
 * border for AI, dashed cyan for synthetic/demo, with the text badge on top.
 * The group is named by its badge so assistive tech announces the provenance.
 */
export function ProvenanceContainer({ kind, label, caption, children, className }: ProvenanceContainerProps) {
  const badgeId = useId()
  return (
    <div
      role="group"
      aria-labelledby={badgeId}
      data-provenance-container={kind}
      className={cn('rounded-lg border px-3 py-2.5', KIND[kind].container, className)}
    >
      <ProvenanceBadge id={badgeId} kind={kind} label={label} />
      <div className="mt-2">{children}</div>
      {caption ? <p className="mt-1 text-xs text-fg-3">{caption}</p> : null}
    </div>
  )
}

/**
 * Provenance label for one data block or row, for sources that carry no
 * synthetic/demo badge of their own. Production `apiGet` skips response
 * validation, so an unrecognised class reaches here unchanged and gets its own
 * wording: falling through to the `real` label would present unknown data as a
 * real market source.
 */
export function ProvenanceSource({ value }: { value: ProvenanceClass }) {
  if (value === 'synthetic') return <ProvenanceBadge kind="synthetic" />
  const label = value === 'real'
    ? 'Real source · not a live quote guarantee'
    : value === 'aggregator'
      ? 'Aggregator · private demo / non-redistributable'
      : 'Source unavailable'
  return <span className="text-xs text-fg-3">{label}</span>
}
